{
  "name": "opencode-autoguard",
  "version": "0.3.0",
  "description": "OpenCode plugin for automatic permission review with local safety rules, LLM judging, circuit breaking, and prompt-injection protection.",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/APLaS-Plus/opencode-autoguard.git"
  },
  "homepage": "https://github.com/APLaS-Plus/opencode-autoguard#readme",
  "bugs": {
    "url": "https://github.com/APLaS-Plus/opencode-autoguard/issues"
  },
  "type": "module",
  "main": "index.ts",
  "module": "index.ts",
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "docs",
    "index.ts",
    "src",
    "CHANGELOG.md"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --experimental-strip-types --test --test-concurrency=1 test/audit.test.ts test/config.test.ts test/rules.test.ts test/rules.eval.test.ts test/tiers.test.ts test/context.test.ts test/circuit.test.ts test/judge.test.ts test/plugin.test.ts",
    "test:integration": "node --experimental-strip-types --test --test-concurrency=1 test/integration.test.ts",
    "eval": "node --experimental-strip-types eval/runner.ts",
    "eval:rules": "node --experimental-strip-types eval/runner.ts --layer=1",
    "check": "npm run typecheck && npm test",
    "prepack": "npm run check"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "permission-review",
    "auto-approve",
    "agent-security",
    "llm-security",
    "guardrails",
    "prompt-injection"
  ],
  "engines": {
    "node": ">=22.14.0",
    "opencode": ">=1.18.18 <2"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.18 <2"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.19",
    "@opencode-ai/sdk": "1.18.19",
    "@types/node": "^22.0.0",
    "typescript": "^5.6.0"
  }
}
